from pathlib import Path
import torch,json,hashlib
R=Path(__file__).resolve().parents[1];out=R/'outputs/T5_Rplus/prior';out.mkdir(exist_ok=True);spec=json.loads((R/'provenance/MoGe_E_round_order_20261106.json').read_text())['models']['S'];p=R/spec['weights_relative'];sha=lambda x:hashlib.sha256(Path(x).read_bytes()).hexdigest();assert sha(p)==spec['sha256'];ck=torch.load(p,map_location='cpu',weights_only=True);state={k.removeprefix('encoder.backbone.'):v for k,v in ck['model'].items() if k.startswith('encoder.backbone.')};assert state;dest=out/'S_backbone.pth';torch.save(state,dest);(out/'S_backbone_receipt.json').write_text(json.dumps({'sha256':sha(dest),'source_weights_sha256':spec['sha256'],'keys':len(state),'path':str(dest),'encoder_config':ck['model_config']['encoder']},indent=2));print('S_BACKBONE_EXPORTED',sha(dest),flush=True)
